// ضعي هذه العقدة Code بعد AI Agent وقبل عقدة إرسال WhatsApp.
// هذه النسخة تقرأ output عندما يكون JSON داخل نص، وتتعامل مع appointment_details.

const input = $input.first().json;

// الاحتفاظ بمعرف الشات إذا كان قادماً من عقدة سابقة.
let previous = {};
try {
  previous = $('Find Original Chat').first().json;
} catch (error) {
  // إذا كان اسم العقدة مختلفاً، يظل الكود يعمل بدون previous.
}

// في الصورة، الـ AI Agent يضع النتيجة داخل output.
let raw = input.output ?? input.text ?? input.response ?? input;
let parsed;

if (typeof raw === 'object' && raw !== null) {
  parsed = raw;
} else {
  let cleaned = String(raw).trim();

  // إزالة علامات Markdown إذا كانت موجودة: ```json ... ```
  cleaned = cleaned
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .replace(/^"""json\s*/i, '')
    .replace(/\s*"""$/i, '')
    .trim();

  try {
    parsed = JSON.parse(cleaned);
  } catch (error) {
    // أحياناً يكون هناك نص قبل JSON؛ نأخذ الجزء بين أول { وآخر }.
    const start = cleaned.indexOf('{');
    const end = cleaned.lastIndexOf('}');

    if (start === -1 || end === -1 || end <= start) {
      throw new Error(`خرج AI Agent ليس JSON صالحاً: ${cleaned}`);
    }

    try {
      parsed = JSON.parse(cleaned.slice(start, end + 1));
    } catch (error2) {
      throw new Error(`تعذر قراءة JSON من خرج AI Agent: ${cleaned}`);
    }
  }
}

// بعض النماذج تضع التفاصيل داخل appointment_details.
const details = parsed.details ?? parsed.appointment_details ?? parsed.booking_details ?? parsed;


// دعم الأسماء الإنجليزية والعربية.
const name = String(
  details.name ??
  details.patient_name ??
  details.customer_name ??
  details.client_name ??
  details.full_name ??
  parsed.name ??
  parsed.patient_name ??
  parsed.customer_name ??
  parsed['الاسم'] ??
  parsed['اسم العميل'] ??
  ''
).trim();

const date = String(
  details.date ??
  details.appointment_date ??
  details.booking_date ??
  details.day ??
  parsed.date ??
  parsed.appointment_date ??
  parsed['التاريخ'] ??
  parsed['تاريخ الموعد'] ??
  ''
).trim();

const time = String(
  details.time ??
  details.appointment_time ??
  details.booking_time ??
  parsed.time ??
  parsed.appointment_time ??
  parsed['الميعاد'] ??
  parsed['الوقت'] ??
  ''
).trim();

if (!name || !date || !time) {
  throw new Error(
    `البيانات ناقصة من AI Agent. تم العثور على: name="${name}", date="${date}", time="${time}". ` +
    `راجعي أن appointment_details يحتوي name/date/time.`
  );
}

const whatsappMessage =
  `أهلاً ${name}،\n\n` +
  `تم حجز موعدك بنجاح.\n` +
  `الاسم: ${name}\n` +
  `التاريخ: ${date}\n` +
  `الميعاد: ${time}\n\n` +
  `ننتظرك في الموعد المحدد.`;

return [
  {
    json: {
      ...previous,
      ...input,
      name,
      date,
      time,
      whatsapp_message: whatsappMessage,
      text: whatsappMessage,
    },
  },
];

// ==================================================
// Code in JavaScript1 — الكود الكامل النهائي
// ==================================================
// يستخدم النود الموجودة عندكِ حالياً:
// 1) get data   : للحصول على رقم العميل
// 2) check list : للحصول على قائمة WhatsApp Chats
// 3) AI Agent   : للحصول على الاسم والتاريخ والميعاد
//
// النتيجة:
// - يختار chat_id للعميل
// - ينشئ رسالة التأكيد القديمة
// - يعرض الوقت مثل: 9:50 صباحاً أو 1:30 مساءً
// ==================================================

// --------------------------------------------------
// 1) قراءة رقم العميل من نود get data
// --------------------------------------------------
const customer = $('get data').first().json;

const rawCustomerPhone = String(
  customer.phone_number ??
  customer.id ??
  ''
).trim();

if (!rawCustomerPhone) {
  throw new Error('لم يتم العثور على رقم العميل في نود get data.');
}

// تحويل رقم العميل إلى صيغة WhatsApp JID.
// مثال: 01551496294 -> 201551496294@s.whatsapp.net
function toWhatsAppJid(phone) {
  const value = String(phone).trim();

  if (value.includes('@')) {
    return value;
  }

  const digits = value.replace(/\D/g, '');

  if (!digits) {
    throw new Error('رقم العميل غير صالح.');
  }

  const internationalPhone = digits.startsWith('0')
    ? `20${digits.slice(1)}`
    : digits.startsWith('20')
      ? digits
      : `20${digits}`;

  return `${internationalPhone}@s.whatsapp.net`;
}

const customerJid = toWhatsAppJid(rawCustomerPhone);

// --------------------------------------------------
// 2) اختيار شات العميل من نود check list
// --------------------------------------------------
const chatList = $('check list').first().json;
const chats = chatList.items ?? [];

// نبحث عن 1-to-1 chat فقط، وليس Group Chat.
const matchingChats = chats.filter((item) => {
  const sameCustomer = [
    item.attendee_public_identifier,
    item.provider_id,
    item.attendee_provider_id,
  ].some((value) => String(value ?? '').trim() === customerJid);

  return sameCustomer && Number(item.type) === 0;
});

if (matchingChats.length === 0) {
  throw new Error(
    `لم يتم العثور على Chat موجود للعميل: ${customerJid}`
  );
}

// إذا ظهر أكثر من Chat، نختار الأحدث.
matchingChats.sort(
  (a, b) =>
    new Date(b.timestamp ?? 0).getTime() -
    new Date(a.timestamp ?? 0).getTime()
);

const chat = matchingChats[0];

// --------------------------------------------------
// 3) قراءة نتيجة AI Agent
// --------------------------------------------------
const aiNode = $('AI Agent').first().json;
let rawAIOutput = aiNode.output ?? aiNode.text ?? aiNode.response ?? aiNode;
let parsed;

if (typeof rawAIOutput === 'object' && rawAIOutput !== null) {
  parsed = rawAIOutput;
} else {
  let cleaned = String(rawAIOutput)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');

  if (start === -1 || end === -1 || end <= start) {
    throw new Error('خرج AI Agent ليس JSON صالحاً.');
  }

  try {
    parsed = JSON.parse(cleaned.slice(start, end + 1));
  } catch (error) {
    throw new Error('تعذر قراءة بيانات الحجز من خرج AI Agent.');
  }
}

// إذا فشل الحجز، لا نرسل رسالة نجاح.
if (parsed.status === 'error') {
  throw new Error(parsed.message ?? 'فشل حجز الموعد في AI Agent.');
}

// يدعم details وappointment_details وbooking_details.
const details =
  parsed.details ??
  parsed.appointment_details ??
  parsed.booking_details ??
  parsed;

const name = String(
  details.name ??
  details.patient_name ??
  details.customer_name ??
  details.client_name ??
  details.full_name ??
  ''
).trim();

const date = String(
  details.date ??
  details.appointment_date ??
  details.booking_date ??
  ''
).trim();

const rawTime = String(
  details.time ??
  details.appointment_time ??
  details.booking_time ??
  ''
).trim();

if (!name || !date || !rawTime) {
  throw new Error(
    `بيانات الحجز ناقصة: name="${name}", date="${date}", time="${rawTime}".`
  );
}

// --------------------------------------------------
// 4) تنسيق الوقت: 09:50:00 -> 9:50 صباحاً
//                    13:30:00 -> 1:30 مساءً
// --------------------------------------------------
function formatArabicTime(value) {
  const match = String(value).trim().match(/^(\d{1,2}):(\d{2})/);

  // إذا لم يكن الوقت بصيغة HH:mm أو HH:mm:ss، نرجعه كما هو.
  if (!match) {
    return String(value).trim();
  }

  let hour24 = Number(match[1]);
  const minutes = match[2];
  const lowerValue = String(value).toLowerCase();

  // يدعم أيضاً مدخلات مثل 9:50 PM أو 9:50 مساءً.
  const isPM = /\bpm\b|مساء/.test(lowerValue);
  const isAM = /\bam\b|صباح/.test(lowerValue);

  if (isPM && hour24 < 12) {
    hour24 += 12;
  }

  if (isAM && hour24 === 12) {
    hour24 = 0;
  }

  const period = hour24 >= 12 ? 'مساءً' : 'صباحاً';
  const hour12 = hour24 % 12 || 12;

  return `${hour12}:${minutes} ${period}`;
}

const time = formatArabicTime(rawTime);

// --------------------------------------------------
// 5) نفس رسالة التأكيد القديمة
// --------------------------------------------------
const whatsappMessage =
  `أهلاً ${name}،\n\n` +
  `تم حجز موعدك بنجاح مع الدكتور.\n` +
  `الاسم: ${name}\n` +
  `التاريخ: ${date}\n` +
  `الميعاد: ${time}\n\n` +
  `ننتظرك في الموعد المحدد.`;

// --------------------------------------------------
// 6) مخرجات هذه النود لنود إرسال UniPile
// --------------------------------------------------
return [
  {
    json: {
      status: 'success',
      original_chat_id: chat.id,
      account_id: chat.account_id,
      customer_jid: customerJid,
      name,
      date,
      time,
      whatsapp_message: whatsappMessage,
      text: whatsappMessage,
    },
  },
];
